package com.getjobs.worker.boss;

import com.microsoft.playwright.*;
import org.json.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class InternshipYingjieshengTest {
    @TempDir Path directory;Playwright playwright;Browser browser;Page page;InternshipStore store;InternshipYingjiesheng adapter;
    @BeforeEach void setup(){String exe=System.getProperty("internship.test-browser");Assumptions.assumeTrue(exe!=null&&Files.isRegularFile(Path.of(exe)));playwright=Playwright.create();browser=playwright.chromium().launch(new BrowserType.LaunchOptions().setExecutablePath(Path.of(exe)).setHeadless(true));page=browser.newContext().newPage();store=new InternshipStore(directory);store.beginRound(1);adapter=new InternshipYingjiesheng(store,JSONObject::new);}
    @AfterEach void close(){if(browser!=null)browser.close();if(playwright!=null)playwright.close();}
    String filter(){return "<div class='mutiselect' style='display:contents'><div class='mutiselect-input' onmouseover=\"this.nextElementSibling.style.display='block'\"><div class='val'>职位类型</div></div><ul style='display:none'><li class='mutiselect-select-item' onclick=\"document.querySelector('.val').textContent='实习'\"><div class='text' title='实习'>实习</div></li></ul></div>";}
    String card(String id,String salary){return "<a class='search-list-href' href='https://q.yingjiesheng.com/jobdetail/"+id+".html'><div>库存分析实习生</div><span class='right-salary'>"+salary+"</span><button onclick=\"sessionStorage.sent='1';return false\">立即申请</button></a>";}
    String listing(){return "<div class='userinfo'>测试同学</div><div class='search-top-input'><input id='keywordInput'><span class='search-button' onclick=\"sessionStorage.keyword=this.previousElementSibling.value\">搜索</span></div>"+filter()+card("100","1.5-2万")+card("200","120-240元/天");}
    String detail(){return "<div class='jobtitle'><div class='job'>库存分析实习生</div><div class='salary'>120-240元/天</div></div><div class='detail-title-left-center'><div class='item'>示例乙城</div><div class='item'>在校生/应届生</div><div class='item'>本科</div><div class='item'>实习</div></div><div class='jobinfo'><div class='text'>负责库存分析需求分析、用户调研、PRD编写和效果评测，实习每周五天、至少三个月。</div></div><div class='detail-content-common'><span class='morecoinfo'>查看更多公司信息</span><div class='text'>测试公司，公司规模为20-99人</div></div>";}
    JSONObject config(String source){return InternshipPolicy.defaults().put("source",source).put("maxScan",1).put("keywords",new JSONArray().put("AI数据分析师")).put("intervalSeconds",5);}
    void route(String detail){page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody(r.request().url().contains("/jobdetail/")?detail:listing())));}
    @Test void canonicalJobLinkDropsRawTrackingButRejectsOtherHosts(){assertEquals("https://q.yingjiesheng.com/jobdetail/200.html",InternshipYingjiesheng.jobUrl("https://q.yingjiesheng.com/jobdetail/200.html?property={\"jobId\":\"200\"}"));assertEquals("",InternshipYingjiesheng.jobUrl("https://q.yingjiesheng.com.evil.test/jobdetail/200.html"));assertEquals("",InternshipYingjiesheng.jobUrl("https://www.51job.com/jobdetail/200.html"));}
    @Test void sessionStatusDoesNotIncludePrivateDiagnosticPageContent(){route(detail());Map<String,Object> result=adapter.checkSession(page);assertEquals(true,result.get("loggedIn"));assertFalse(result.containsKey("pageText"));assertFalse(result.containsKey("elements"));}
    @Test void recommendationPinsInternshipAndPreexcludesMonthlyWithoutApplying(){route(detail());List<JSONObject> jobs=new ArrayList<>();adapter.collect(config("recommend"),page,()->false,jobs::add,s->{});assertEquals(1,jobs.size());assertEquals("测试公司",jobs.getFirst().getString("company"));assertEquals("实习",jobs.getFirst().getString("employmentType"));assertEquals(1,store.roundSummary().getInt("preExcluded"));assertEquals("实习",page.locator(".val").innerText());assertNull(page.evaluate("sessionStorage.sent"));}
    @Test void alreadySelectedInternshipDoesNotRequireUnmountedDropdownOptions(){String ready="<div style='display:none'>"+filter()+"</div>"+listing().replace(filter(),"<div class='mutiselect'><div class='mutiselect-input'><div class='val'>实习</div></div></div>");page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody(r.request().url().contains("/jobdetail/")?detail():ready)));List<JSONObject> jobs=new ArrayList<>();adapter.collect(config("recommend"),page,()->false,jobs::add,s->{});assertEquals(1,jobs.size());}
    @Test void searchUsesSavedKeywordAndStillPinsInternship(){String list="<div style='display:none'><input id='keywordInput'><span class='search-button' onclick=\"sessionStorage.hiddenClicked='1'\">隐藏搜索</span></div>"+listing();page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody(r.request().url().contains("/jobdetail/")?detail():list)));List<JSONObject> jobs=new ArrayList<>();adapter.collect(config("search"),page,()->false,jobs::add,s->{});assertEquals("AI数据分析师",page.evaluate("sessionStorage.keyword"));assertNull(page.evaluate("sessionStorage.hiddenClicked"));assertEquals("AI数据分析师",jobs.getFirst().getString("sourceKeyword"));assertEquals("search",jobs.getFirst().getString("source"));assertEquals("实习",page.locator(".val").innerText());}
    @Test void fullTimeDailySalaryPostingCannotEnterInternshipCandidates(){route(detail().replace("<div class='item'>实习</div>","<div class='item'>全职</div>"));List<JSONObject> jobs=new ArrayList<>();adapter.collect(config("recommend"),page,()->false,jobs::add,s->{});assertTrue(jobs.isEmpty());assertEquals(2,store.roundSummary().getInt("preExcluded"));}
    @Test void downstreamModelFailureIsNotSwallowedAsAReadError(){route(detail());var e=assertThrows(IllegalStateException.class,()->adapter.collect(config("recommend"),page,()->false,j->{throw new IllegalStateException("model failed");},s->{}));assertEquals("model failed",e.getMessage());assertTrue(store.readFailures().isEmpty());}
    @Test void newSiteCannotReuseOldNativeDeliveryFlow(){route(detail());page.navigate("https://q.yingjiesheng.com/jobdetail/200.html");assertThrows(IllegalStateException.class,()->adapter.deliver(config("recommend"),"job",new JSONObject(),page,()->false));assertNull(page.evaluate("sessionStorage.sent"));}
    void deliveryRoute(String controls){page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody("<div class='userinfo'>测试同学</div>"+detail()+"<div class='detail-title-right'>"+controls+"</div>")));adapter=new InternshipYingjiesheng(store,()->new JSONObject().put("resumeReady",true));}
    JSONObject deliveryEntry(){page.navigate("https://q.yingjiesheng.com/jobdetail/200.html");JSONObject entry=new JSONObject().put("job",adapter.readJob(page,page.url())).put("status","screened");store.save("job",entry);return entry;}
    @Test void automaticSubmissionRequiresPersistedSameJobReceipt(){deliveryRoute("<div class='delivery-btn' onclick=\"localStorage.applied='1';this.innerText='已申请'\">立即申请</div><script>if(localStorage.applied)document.querySelector('.delivery-btn').innerText='已申请'</script>");assertTrue(adapter.deliver(config("recommend"),"job",deliveryEntry(),page,()->false));assertEquals("complete",store.get("job").getString("status"));assertTrue(store.get("job").getBoolean("nativeResumeConfirmed"));assertEquals(InternshipYingjiesheng.ADAPTER,store.scheduleState().getJSONObject("nativeAcceptance").getString("adapter"));}
    @Test void alreadyAppliedDoesNotGrantAutomaticAcceptance(){deliveryRoute("<div class='delivery-btn'>已申请</div>");assertFalse(adapter.deliver(config("recommend"),"job",deliveryEntry(),page,()->false));assertFalse(store.scheduleState().has("nativeAcceptance"));}
    @Test void vanishedReceiptRemainsLocked(){deliveryRoute("<div class='delivery-btn' onclick=\"this.innerText='已申请'\">立即申请</div>");assertThrows(IllegalStateException.class,()->adapter.deliver(config("recommend"),"job",deliveryEntry(),page,()->false));assertEquals("native_attempted",store.get("job").getString("status"));assertFalse(store.scheduleState().has("nativeAcceptance"));}
    @Test void oldAdapterEntryCannotSubmitNewSite(){deliveryRoute("<div class='delivery-btn' onclick=\"localStorage.sent='1'\">立即申请</div>");JSONObject entry=deliveryEntry();entry.getJSONObject("job").put("siteAdapter","retired-51job");assertThrows(IllegalStateException.class,()->adapter.deliver(config("recommend"),"job",entry,page,()->false));assertNull(page.evaluate("localStorage.sent"));}
    @Test void unrelatedRecommendedAppliedButtonIsNotAReceipt(){deliveryRoute("<div class='delivery-btn'>立即申请</div>");page.navigate("https://q.yingjiesheng.com/jobdetail/200.html");page.locator("body").evaluate("el=>el.insertAdjacentHTML('beforeend',`<div class='delivery-btn'>已申请</div><div>投递成功</div>`)");assertFalse(adapter.submitted(page));}
    @Test void quotaPersistsOnlyForThisPlatform(){deliveryRoute("<div>今日投递次数已达到上限</div>");page.navigate("https://q.yingjiesheng.com/jobdetail/200.html");assertThrows(IllegalStateException.class,()->adapter.check(page));JSONObject states=store.scheduleState().getJSONObject("platforms");assertTrue(states.getJSONObject("job51").has("quotaDate"));assertFalse(states.getJSONObject("boss").has("quotaDate"));}
    @Test void stickyDuplicateRenderedAfterSearchDoesNotBreakKeywordVerification(){String list=listing().replace("sessionStorage.keyword=this.previousElementSibling.value","sessionStorage.keyword=this.previousElementSibling.value;document.body.appendChild(this.parentElement.cloneNode(true))");page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody(r.request().url().contains("/jobdetail/")?detail():list)));List<JSONObject> jobs=new ArrayList<>();adapter.collect(config("search"),page,()->false,jobs::add,s->{});assertEquals(2,page.locator("#keywordInput:visible").count());assertEquals(1,jobs.size());assertEquals("AI数据分析师",jobs.getFirst().getString("sourceKeyword"));}
    @Test void twoInitiallyVisibleSearchFormsUseOnePairedFormOnly(){String list=listing()+"<div class='search-top-input'><input id='keywordInput'><span class='search-button' onclick=\"sessionStorage.wrongForm='1'\">搜索</span></div>";page.context().route("**/*",r->r.fulfill(new Route.FulfillOptions().setContentType("text/html; charset=utf-8").setBody(list)));page.navigate("https://q.yingjiesheng.com/pc/searchintern");adapter.search(page,"数据分析师");assertEquals("数据分析师",page.evaluate("sessionStorage.keyword"));assertNull(page.evaluate("sessionStorage.wrongForm"));}
}
